from collections import Counter

class Solution:
    def canReorderDoubled(self, arr: list[int]) -> bool:
        counts = Counter(arr)
        for x in sorted(counts.keys(), key=abs):
            if counts[x] > counts[2 * x]:
                return False
            counts[2 * x] -= counts[x]
        return True

class Solution {
public:
    bool canReorderDoubled(vector<int>& arr) {
        unordered_map<int, int> counts;
        for (int x : arr) counts[x]++;
        vector<int> keys;
        for (auto& [k, _] : counts) keys.push_back(k);
        sort(keys.begin(), keys.end(), [](int a, int b) {
            return abs(a) < abs(b);
        });
        for (int x : keys) {
            if (counts[x] > counts[2 * x]) return false;
            counts[2 * x] -= counts[x];
        }
        return true;
    }
};

class Solution {
    public boolean canReorderDoubled(int[] arr) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int x : arr) counts.put(x, counts.getOrDefault(x, 0) + 1);
        List<Integer> keys = new ArrayList<>(counts.keySet());
        keys.sort((a, b) -> Integer.compare(Math.abs(a), Math.abs(b)));
        for (int x : keys) {
            if (counts.get(x) > counts.getOrDefault(2 * x, 0)) return false;
            counts.put(2 * x, counts.get(2 * x) - counts.get(x));
        }
        return true;
    }
}

var canReorderDoubled = function(arr) {
    const counts = new Map();
    for (const x of arr) counts.set(x, (counts.get(x) || 0) + 1);
    const keys = Array.from(counts.keys()).sort((a, b) => Math.abs(a) - Math.abs(b));
    for (const x of keys) {
        const cx = counts.get(x);
        if (cx > (counts.get(2 * x) || 0)) return false;
        counts.set(2 * x, counts.get(2 * x) - cx);
    }
    return true;
};
